document.addEventListener("DOMContentLoaded",(()=>{const e=document.querySelector(".form-section form");e&&e.addEventListener("submit",(async r=>{r.preventDefault();const t={name:e.name.value.trim(),email:e.email.value.trim(),message:e.message.value.trim()};try{const r=await fetch("https://projectrunway-api-175ac734850a.herokuapp.com/api/inquiries",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)}),a=await r.json();if(!a.success)throw new Error(a.error||"Server error");alert("Message sent!"),e.reset()}catch(e){console.error("Form submission error:",e),alert("Failed to send message. ❌")}}))}));